/** Private visible opt-in and revoke UI. No installed app is automatically trusted or launched. */
public final class AlarmAccessActivity extends Activity {
 private final SensitiveReviewTouches reviewTouches=new SensitiveReviewTouches();
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){return reviewTouches.dispatch(this,event,super::dispatchTouchEvent);}

    private String packageName="",message="",issue="",preview="";private AlarmAccessGrants.Snapshot snapshot;private Map<String,String> statuses=Map.of();private AlarmAccessGrants.Identity verified;private boolean consent,resumed;private EditText packageInput;private Operation operation;private final Handler main=new Handler(Looper.getMainLooper());
    private enum Kind{LOAD,VERIFY,ALLOW,REVOKE,REVOKE_ALL,PREVIEW}
    private static final ExecutorService WORKER=Executors.newSingleThreadExecutor(r->new Thread(r,"SleepWell alarm access"));
    private static final class Operation {final Kind kind;volatile boolean done,cancelled;volatile String issue="",message="",preview="";volatile AlarmAccessGrants.Snapshot snapshot;volatile AlarmAccessGrants.Identity identity;volatile Map<String,String> statuses=Map.of();final CancellationSignal cancellation=new CancellationSignal();Operation(Kind kind){this.kind=kind;}boolean mutation(){return kind==Kind.ALLOW||kind==Kind.REVOKE||kind==Kind.REVOKE_ALL;}void cancel(){if(!mutation()){cancelled=true;cancellation.cancel();}}}
    private static Operation work(Context context,Kind kind,String pkg,AlarmAccessGrants.Identity identity,long revision){Context app=context.getApplicationContext();Operation op=new Operation(kind);WORKER.execute(()->{try{if(op.cancelled)return;switch(kind){case VERIFY:op.identity=AlarmAccessGrants.inspect(app,pkg);op.message="Installed package and current signer verified. Review, then explicitly Allow.";break;case ALLOW:if(identity==null)throw new IllegalStateException("Verify the installed app first.");AlarmAccessGrants.allow(app,identity,revision);op.message="Alarm-management access allowed. No alarm was created or changed by allowing access.";break;case REVOKE:AlarmAccessGrants.revoke(app,pkg,revision);op.message="New API actions revoked for this app. Previously saved alarms and returned copies remain.";break;case REVOKE_ALL:AlarmAccessGrants.revokeAll(app,"All alarm-management grants revoked. Allow each app explicitly to manage alarms again.");op.message="All new external API actions revoked. Previously saved alarms and returned copies remain.";break;case PREVIEW:op.preview=preview(app,op.cancellation);op.message="Local self-preview only. No external app was granted access and no alarm was changed.";break;default:break;}if(op.cancelled)return;op.snapshot=AlarmAccessGrants.snapshot(app);Map<String,String> statuses=new LinkedHashMap<>();for(AlarmAccessGrants.Grant grant:op.snapshot.grants)statuses.put(grant.identity.pkg,AlarmAccessGrants.status(app,grant));op.statuses=Map.copyOf(statuses);}catch(RuntimeException unavailable){op.issue=unavailable.getMessage()==null?"Alarm access could not complete. Refresh or Revoke all.":unavailable.getMessage();}finally{op.done=true;}});return op;}
    private static String preview(Context c,CancellationSignal signal){StringBuilder text=new StringBuilder();try(Cursor cursor=c.getContentResolver().query(AlarmContentContract.ALARMS.buildUpon().appendQueryParameter("limit","3").build(),new String[]{"_id","hour","minute","label","enabled","writable","write_issue","scheduling_status"},null,null,null,signal)){if(cursor==null)throw new IllegalStateException("The local alarm provider returned no cursor.");while(cursor.moveToNext()){if(text.length()>0)text.append("\n\n");text.append("#").append(cursor.getInt(0)).append(" · ").append(cursor.isNull(3)?"Unrepresentable alarm":cursor.getString(3));if(!cursor.isNull(1)&&!cursor.isNull(2))text.append(" · ").append(String.format(Locale.ROOT,"%02d:%02d",cursor.getInt(1),cursor.getInt(2)));text.append("\n").append(cursor.isNull(4)?"State unknown":cursor.getInt(4)==1?"Enabled":"Off").append(" · ").append(cursor.getInt(5)==1?"Supported for writes":cursor.getString(6)).append("\nScheduling · ").append(cursor.getString(7));}return text.length()==0?"No saved alarms. No sample alarm was created.":text.toString();}}
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);if(state!=null){packageName=state.getString("package","");message=state.getString("message","");issue=state.getString("issue","");}Object retained=getLastNonConfigurationInstance();if(retained instanceof Operation owned)operation=owned;else operation=work(this,Kind.LOAD,"",null,0);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);render();}
    private boolean busy(){return operation!=null&&!operation.done;}
    private void render(){boolean busy=busy();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Alarm app access",this::back);Design.space(body,8);LinearLayout scope=IntegrationSetupUi.section(body,"What the app can manage");IntegrationSetupUi.detail(scope,"Read clock summaries, create ordinary clock alarms, and edit or delete supported alarms. Saved sound and challenges are preserved. Complex schedules remain read-only.");LinearLayout access=IntegrationSetupUi.section(body,"Before allowing access");IntegrationSetupUi.detail(access,"The app can make supported edits without asking each time. Enabled alarms may ring later. It cannot ring now or stop an active alarm.");IntegrationSetupUi.detail(access,"Revoking stops new API actions; saved alarms and returned copies remain. Allow again after reboot, restore, or a change in the app’s signer or UID.");Design.space(body,16);
        Design.text(body,"Installed app package",13,600,Design.INK);packageInput=new EditText(this);packageInput.setSingleLine(true);packageInput.setTypeface(Design.font(this,400));packageInput.setTextColor(Design.INK);packageInput.setTextSize(15*Appearance.scale(this));packageInput.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);packageInput.setFilters(new InputFilter[]{new InputFilter.LengthFilter(255)});packageInput.setHint("com.example.reader");packageInput.setHintTextColor(Design.MUTED);packageInput.setContentDescription("Installed app package name");packageInput.setText(packageName);packageInput.setBackground(Design.shape(this,Design.SOFT,12));Design.pad(packageInput,12,10);body.addView(packageInput,new LinearLayout.LayoutParams(-1,Design.dp(this,52)));packageInput.setEnabled(!busy);packageInput.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int before,int count){packageName=s.toString().strip();if(verified!=null&&!verified.pkg.equals(packageName)){verified=null;consent=false;}}public void afterTextChanged(Editable e){}});Design.text(body,"Enter the exact package name of an installed app. Android must be able to identify it; apps with shared UIDs cannot be allowed. Verification does not launch the app.",12,400,Design.MUTED);Design.button(body,"Verify installed package",false,()->begin(Kind.VERIFY,packageName)).setEnabled(!busy);
        if(verified!=null&&verified.pkg.equals(packageName)){AlarmAccessGrants.Identity reviewed=verified;Design.space(body,10);Design.text(body,verified.name+" · "+verified.pkg,15,600,Design.INK);Design.text(body,"UID "+verified.uid+" · current signer SHA-256\n"+verified.signers.replace(",","\n"),11,400,Design.MUTED);CheckBox accept=new CheckBox(this);accept.setTypeface(Design.font(this,400));accept.setTextColor(Design.INK);accept.setTextSize(13*Appearance.scale(this));accept.setButtonTintList(ColorStateList.valueOf(Design.BROWN));accept.setText("I trust this verified app to read, create, change and delete supported alarms without per-request review, including enabling alarms that may ring later, until access expires or I revoke it.");accept.setChecked(consent);accept.setMinHeight(Design.dp(this,48));accept.setEnabled(!busy);accept.setOnCheckedChangeListener((button,on)->consent=on);body.addView(accept);Design.button(body,"Allow alarm management",true,()->{if(!consent){issue="Confirm the alarm-management scope before allowing this app.";render();return;}begin(Kind.ALLOW,reviewed.pkg);}).setEnabled(!busy&&snapshot!=null);}
        Design.space(body,18);Design.text(body,"Managed apps",17,600,Design.INK);if(snapshot==null)Design.text(body,busy?"Opening private access settings…":"Alarm-access state unavailable · Revoke all or refresh.",13,400,Design.MUTED);else if(snapshot.grants.isEmpty())Design.text(body,"No apps are allowed.",14,400,Design.MUTED);else for(AlarmAccessGrants.Grant grant:snapshot.grants){Design.space(body,10);Design.text(body,grant.identity.name+" · "+grant.identity.pkg,14,600,Design.INK);Design.text(body,statuses.getOrDefault(grant.identity.pkg,"Needs verification"),12,500,Design.BROWN);Design.text(body,"UID "+grant.identity.uid+" · signer SHA-256\n"+grant.identity.signers.replace(",","\n"),10,400,Design.MUTED);Design.button(body,"Revoke "+grant.identity.pkg,false,()->begin(Kind.REVOKE,grant.identity.pkg)).setEnabled(!busy);Design.line(body);}
        if(snapshot!=null&&!snapshot.status.isEmpty()){Design.space(body,8);Design.text(body,snapshot.status,12,400,Design.MUTED);}Design.space(body,10);Design.button(body,"Preview local alarm summaries",false,()->begin(Kind.PREVIEW,"")).setEnabled(!busy);if(!preview.isEmpty()){Design.space(body,10);Design.text(body,preview,12,400,Design.MUTED);}Design.space(body,12);String last=AlarmAccessGrants.operationStatus(this);if(!last.isEmpty())Design.text(body,last,12,500,Design.BROWN);LinearLayout endpoint=IntegrationSetupUi.section(body,"Provider endpoint");IntegrationSetupUi.copy(this,endpoint,"Copy endpoint",AlarmContentContract.ALARMS.toString());if(!message.isEmpty()){Design.space(body,10);Design.text(body,message,13,500,Design.BROWN);}if(!issue.isEmpty()){Design.space(body,10);TextView error=Design.text(body,issue,13,500,NightDialTokens.NEGATIVE);error.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}LinearLayout footer=RecordUi.footer(body);LinearLayout maintenance=Design.row(this);footer.addView(maintenance);IntegrationSetupUi.pairedAction(maintenance,busy?"Working…":"Refresh",!busy,()->begin(Kind.LOAD,"")).setContentDescription("Refresh alarm-access status");IntegrationSetupUi.pairedAction(maintenance,"Revoke all",!busy,()->begin(Kind.REVOKE_ALL,"")).setContentDescription("Revoke all apps");Design.button(footer,"Close",false,this::back).setEnabled(!busy||!operation.mutation());}
    private void begin(Kind kind,String pkg){if(!resumed||!hasWindowFocus()||busy())return;if(packageInput!=null)packageName=packageInput.getText().toString().strip();AlarmAccessGrants.Identity identity=verified;long revision=snapshot==null?-1:snapshot.revision;if(kind==Kind.ALLOW&&(identity==null||!identity.pkg.equals(packageName)||!consent)){issue="Verify this installed package and confirm the scope first.";render();return;}if(kind==Kind.VERIFY)pkg=packageName;operation=work(getApplicationContext(),kind,pkg,identity,revision);if(kind==Kind.ALLOW)consent=false;message="";issue="";render();main.removeCallbacks(poll);main.post(poll);}
    private final Runnable poll=new Runnable(){public void run(){if(!resumed||isFinishing()||isDestroyed())return;Operation done=operation;if(done!=null&&done.done){operation=null;if(!done.cancelled){if(done.snapshot!=null){snapshot=done.snapshot;statuses=done.statuses;}if(done.kind==Kind.VERIFY){verified=done.identity;consent=false;}else if(done.kind==Kind.ALLOW||done.kind==Kind.REVOKE_ALL){verified=null;consent=false;}message=done.message;issue=done.issue;if(done.kind==Kind.PREVIEW)preview=done.preview;}render();}main.postDelayed(this,200);}};
    @Override protected void onResume(){super.onResume();resumed=true;main.removeCallbacks(poll);main.post(poll);}
    @Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}
    private void back(){if(busy()&&operation.mutation())return;if(operation!=null)operation.cancel();finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override public Object onRetainNonConfigurationInstance(){return operation;}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(packageInput!=null)packageName=packageInput.getText().toString().strip();state.putString("package",packageName);state.putString("message",message);state.putString("issue",issue);}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);if(!isChangingConfigurations()&&operation!=null)operation.cancel();super.onDestroy();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
